import "server-only";
import {ApiError} from "@/lib/server/http";
import {randomUUID} from "node:crypto";
import type {PoolClient} from "pg";
import {withTenant} from "@/lib/server/db";
import {audit} from "@/lib/server/audit";
import {domainConfig} from "@/config/domain";

export type RecordInput={module:string;status:string;row:string[];fields:Record<string,string>;positions?:unknown[];metadata?:Record<string,unknown>};
export type RecordDto={id:string;module:string;status:string;row:string[];fields:Record<string,string>;positions?:unknown[];metadata:Record<string,unknown>;createdBy?:string|null;createdAt?:Date|string;updatedAt?:Date|string};

type Obj=Record<string,unknown>;
const moduleTables:Record<string,string>={
 kunden:"customers",offerten:"quotes",auftraege:"orders",projekte:"projects",zeiterfassung:"time_entries",spesen:"expenses",rechnungen:"invoices",zahlungen:"payments",mwst:"vat_periods",personal:"employees",lohn:"payroll_runs",lieferanten:"suppliers",eingangsrechnungen:"supplier_invoices",produkte:"products_services",buchhaltung:"accounting_entries",bank:"bank_transactions",aufgaben:"tasks",abwesenheiten:"absences",dokumente:"business_documents",vertraege:"contracts"
};
const money=(value:unknown)=>new Intl.NumberFormat("de-CH",{style:"currency",currency:"CHF"}).format(Number(value)||0);
const text=(value:unknown)=>typeof value==="string"?value:"";
const num=(value:unknown)=>{if(typeof value==="number")return Number.isFinite(value)?value:0;const normalized=text(value).replace(/[^0-9,.-]/g,"").replace(/[’']/g,"").replace(",",".");return Number(normalized)||0};
const yes=(value:unknown)=>["ja","true","1"].includes(text(value).trim().toLowerCase());
const iso=(value:unknown)=>value instanceof Date?value.toISOString().slice(0,10):text(value).slice(0,10);
const relations=(input:Partial<RecordInput>)=>{const m=input.metadata;const r=m&&typeof m.relations==="object"&&m.relations&&!Array.isArray(m.relations)?m.relations as Record<string,unknown>:{};return Object.fromEntries(Object.entries(r).map(([k,v])=>[k,text(v)])) as Record<string,string>};
const ext=()=>randomUUID();

async function pk(client:PoolClient,table:string,organizationId:string,externalId?:string|null){
 if(!externalId)return null;
 const allowed=new Set(Object.values(moduleTables));if(!allowed.has(table))throw new Error("invalid_relation_table");
 const r=await client.query<{id:string}>(`select id::text from ${table} where organization_id=$1 and external_id=$2 and archived_at is null limit 1`,[organizationId,externalId]);
 return r.rows[0]?.id||null;
}
async function external(client:PoolClient,table:string,organizationId:string,id?:string|null){if(!id)return "";const allowed=new Set(Object.values(moduleTables));if(!allowed.has(table))return "";const r=await client.query<{external_id:string}>(`select external_id from ${table} where organization_id=$1 and id=$2 limit 1`,[organizationId,id]);return r.rows[0]?.external_id||""}

function statusDb(moduleKey:string,value:string){const v=value.trim().toLowerCase();switch(moduleKey){
 case"kunden":case"lieferanten":case"produkte":return /inaktiv/.test(v)?"inactive":"active";
 case"projekte":return /abgeschlossen/.test(v)?"completed":/blockiert/.test(v)?"blocked":/storniert/.test(v)?"cancelled":/geplant/.test(v)?"planned":/laufend/.test(v)?"active":"in_progress";
 case"auftraege":return /abgeschlossen/.test(v)?"completed":/storniert/.test(v)?"completed":/bereit/.test(v)?"paused":"active";
 case"offerten":return /angenommen/.test(v)?"accepted":/abgelehnt/.test(v)?"declined":/abgelaufen/.test(v)?"expired":/entwurf/.test(v)?"draft":"sent";
 case"rechnungen":return /teil/.test(v)?"partial":/bezahlt/.test(v)?"paid":/überfällig/.test(v)?"overdue":/storniert/.test(v)?"cancelled":/entwurf/.test(v)?"draft":"sent";
 case"eingangsrechnungen":return /bezahlt/.test(v)?"paid":/freigegeben/.test(v)?"open":/überfällig/.test(v)?"review":"open";
 case"spesen":return /freigegeben/.test(v)?"approved":/verbucht/.test(v)?"posted":/abgelehnt/.test(v)?"rejected":"open";
 case"eingangsrechnungen":return /bezahlt/.test(v)?"paid":/überfällig/.test(v)?"review":/freigegeben|freigabe/.test(v)?"review":"open";
 case"aufgaben":return /erledigt/.test(v)?"done":/arbeit/.test(v)?"in_progress":"open";
 case"abwesenheiten":return /genehmigt/.test(v)?"approved":/abgelehnt/.test(v)?"rejected":"open";
 case"buchhaltung":return /verbucht/.test(v)?"posted":"draft";
 case"bank":return /zugeordnet/.test(v)?"matched":/verbucht/.test(v)?"booked":"open";
 case"mwst":return /abgeschlossen/.test(v)?"closed":/eingereicht/.test(v)?"filed":/vorbereitung/.test(v)?"prepared":"draft";
 case"lohn":return /bezahlt|ausgezahlt/.test(v)?"paid":/freigegeben|bereit/.test(v)?"approved":"draft";
 case"dokumente":return /archiviert/.test(v)?"archived":"current";
 case"vertraege":return /gekündigt|storniert/.test(v)?"cancelled":/abgelaufen/.test(v)?"ended":/entwurf/.test(v)?"draft":"active";
 default:return value;
 }}
function statusUi(moduleKey:string,value:string){switch(moduleKey){
 case"kunden":case"lieferanten":case"produkte":return value==="inactive"?"Inaktiv":"Aktiv";
 case"projekte":return ({planned:"Geplant",in_progress:"In Arbeit",active:"Laufend",blocked:"Blockiert",completed:"Abgeschlossen",cancelled:"Storniert"} as Record<string,string>)[value]||value;
 case"auftraege":return ({paused:"Bereit",active:"In Arbeit",completed:"Abgeschlossen"} as Record<string,string>)[value]||value;
 case"offerten":return ({draft:"Entwurf",sent:"Offen",accepted:"Angenommen",declined:"Abgelehnt",expired:"Abgelaufen",revised:"Überarbeitet"} as Record<string,string>)[value]||value;
 case"rechnungen":return ({draft:"Entwurf",sent:"Offen",partial:"Teilbezahlt",paid:"Bezahlt",overdue:"Überfällig",cancelled:"Storniert"} as Record<string,string>)[value]||value;
 case"spesen":return ({open:"Offen",approved:"Freigegeben",posted:"Verbucht",rejected:"Abgelehnt"} as Record<string,string>)[value]||value;
 case"eingangsrechnungen":return ({open:"Offen",review:"Zur Freigabe",paid:"Bezahlt"} as Record<string,string>)[value]||value;
 case"bank":return ({open:"Offen",matched:"Zugeordnet",booked:"Verbucht",ignored:"Ignoriert"} as Record<string,string>)[value]||value;
 case"mwst":return ({draft:"Entwurf",prepared:"In Vorbereitung",filed:"Eingereicht",paid:"Bezahlt",closed:"Abgeschlossen"} as Record<string,string>)[value]||value;
 case"lohn":return ({draft:"Entwurf",review:"Zur Prüfung",approved:"Bereit",paid:"Bezahlt",cancelled:"Storniert"} as Record<string,string>)[value]||value;
 case"aufgaben":return ({open:"Offen",in_progress:"In Arbeit",done:"Erledigt",cancelled:"Storniert"} as Record<string,string>)[value]||value;
 case"abwesenheiten":return ({open:"Offen",approved:"Genehmigt",rejected:"Abgelehnt",cancelled:"Storniert"} as Record<string,string>)[value]||value;
 case"buchhaltung":return value==="posted"?"Verbucht":"Entwurf";
 case"dokumente":return value==="archived"?"Archiviert":"Aktuell";
 case"vertraege":return ({draft:"Entwurf",active:"Aktiv",paused:"Pausiert",ended:"Abgelaufen",cancelled:"Gekündigt"} as Record<string,string>)[value]||value;
 default:return value;
 }}

async function lines(client:PoolClient,moduleKey:string,organizationId:string,parentId:string){
 const def=moduleKey==="offerten"?{table:"quote_lines",fk:"quote_id"}:moduleKey==="rechnungen"?{table:"invoice_lines",fk:"invoice_id"}:moduleKey==="vertraege"?{table:"contract_lines",fk:"contract_id"}:null;if(!def)return undefined;
 const r=await client.query(`select description,quantity::float8 as quantity,unit_price::float8 as "unitPrice",vat_rate::float8 as "vatRate" from ${def.table} where organization_id=$1 and ${def.fk}=$2 order by sort_order,id`,[organizationId,parentId]);return r.rows;
}
async function notes(client:PoolClient,organizationId:string,moduleKey:string,externalId:string){const r=await client.query<{note_text:string}>(`select note_text from entity_notes where organization_id=$1 and entity_type=$2 and entity_external_id=$3 order by created_at desc`,[organizationId,moduleKey,externalId]);return r.rows.map(x=>x.note_text)}
async function syncNotes(client:PoolClient,organizationId:string,userId:string,moduleKey:string,externalId:string,metadata?:Record<string,unknown>){if(!metadata||!Array.isArray(metadata.notes))return;const list=metadata.notes.filter((x):x is string=>typeof x==="string"&&x.trim().length>0);await client.query(`delete from entity_notes where organization_id=$1 and entity_type=$2 and entity_external_id=$3`,[organizationId,moduleKey,externalId]);for(const n of [...list].reverse())await client.query(`insert into entity_notes(organization_id,entity_type,entity_external_id,note_text,created_by_user_id) values($1,$2,$3,$4,$5)`,[organizationId,moduleKey,externalId,n,userId])}

