async function replaceRecord(client:PoolClient,organizationId:string,userId:string,id:string,moduleKey:string,input:Partial<RecordInput>){await protectBusinessRecord(client,organizationId,id,moduleKey);const currentRows=await selectRows(client,organizationId,moduleKey,id);if(!currentRows[0])return false;const current=await rowToDto(client,moduleKey,organizationId,currentRows[0]);const merged:RecordInput={module:moduleKey,status:input.status??current.status,row:input.row??current.row,fields:input.fields??current.fields,positions:input.positions??current.positions,metadata:{...current.metadata,...(input.metadata||{})}};await updateInPlace(client,organizationId,userId,id,moduleKey,merged);return true}
async function protectBusinessRecord(client:PoolClient,organizationId:string,id:string,moduleKey:string){
 if(moduleKey==='zahlungen')throw new ApiError(409,'payment_locked','Verbuchte Zahlungen müssen nachvollziehbar korrigiert werden.');
 if(moduleKey==='rechnungen'&&(await client.query("select id from invoices where organization_id=$1 and external_id=$2 and status<>'draft' for update",[organizationId,id])).rowCount)throw new ApiError(409,'document_locked','Ausgestellte Rechnungen können nicht geändert oder entfernt werden.');
 if(moduleKey==='offerten'&&(await client.query("select q.id from quotes q where q.organization_id=$1 and q.external_id=$2 and (q.status<>'draft' or exists(select 1 from invoices i where i.organization_id=q.organization_id and i.source_quote_id=q.id) or exists(select 1 from projects p where p.organization_id=q.organization_id and p.source_quote_id=q.id)) for update",[organizationId,id])).rowCount)throw new ApiError(409,'document_locked','Dieses Angebot hat bereits einen Geschäftsvorgang.');
 if(moduleKey==='zeiterfassung'&&(await client.query('select id from time_entries where organization_id=$1 and external_id=$2 and invoiced_invoice_id is not null for update',[organizationId,id])).rowCount)throw new ApiError(409,'time_locked','Verrechnete Zeiteinträge können nicht geändert oder entfernt werden.');
}
async function archiveRecord(client:PoolClient,organizationId:string,id:string,moduleKey:string){await protectBusinessRecord(client,organizationId,id,moduleKey);const table=moduleTables[moduleKey];if(!table)return false;if(["vat_periods","payroll_runs","business_documents"].includes(table)){const r=await client.query(`delete from ${table} where organization_id=$1 and external_id=$2`,[organizationId,id]);return Boolean(r.rowCount)}const r=await client.query(`update ${table} set archived_at=now(),updated_at=now() where organization_id=$1 and external_id=$2 and archived_at is null`,[organizationId,id]);return Boolean(r.rowCount)}

export async function getRecordHeader(organizationId:string,userId:string,id:string){return withTenant(organizationId,userId,async client=>{for(const moduleKey of Object.keys(moduleTables)){const rows=await selectRows(client,organizationId,moduleKey,id);if(rows[0])return {id,module:moduleKey,createdBy:text(rows[0].created_by_user_id)};}return null})}
export async function getRecord(organizationId:string,userId:string,id:string,ownOnly=false){return withTenant(organizationId,userId,async client=>{for(const moduleKey of Object.keys(moduleTables)){const rows=await selectRows(client,organizationId,moduleKey,id);const row=rows[0];if(!row)continue;if(ownOnly&&text(row.created_by_user_id)!==userId)return null;return rowToDto(client,moduleKey,organizationId,row)}return null})}
export async function listRecords(organizationId:string,userId:string,moduleKey:string,ownOnly=false){return withTenant(organizationId,userId,async client=>{if(!moduleTables[moduleKey])return [];const rows=await selectRows(client,organizationId,moduleKey);const filtered=ownOnly?rows.filter(r=>text(r.created_by_user_id)===userId):rows;return Promise.all(filtered.map(r=>rowToDto(client,moduleKey,organizationId,r)))})}
export async function createRecord(organizationId:string,userId:string,input:RecordInput){return withTenant(organizationId,userId,async client=>{const id=ext();await insertRecord(client,organizationId,userId,input,id);await audit(client,{organizationId,userId,action:`${input.module}.created`,entityType:input.module,entityId:id});const rows=await selectRows(client,organizationId,input.module,id);return rowToDto(client,input.module,organizationId,rows[0])})}
export async function updateRecord(organizationId:string,userId:string,id:string,input:Partial<RecordInput>,ownOnly=false){return withTenant(organizationId,userId,async client=>{const header=await getHeaderInClient(client,organizationId,id);if(!header||ownOnly&&header.createdBy!==userId)return null;const ok=await replaceRecord(client,organizationId,userId,id,header.module,input);if(!ok)return null;await audit(client,{organizationId,userId,action:`${header.module}.updated`,entityType:header.module,entityId:id});const rows=await selectRows(client,organizationId,header.module,id);return rowToDto(client,header.module,organizationId,rows[0])})}
export async function deleteRecord(organizationId:string,userId:string,id:string,ownOnly=false){return withTenant(organizationId,userId,async client=>{const header=await getHeaderInClient(client,organizationId,id);if(!header||ownOnly&&header.createdBy!==userId)return false;const ok=await archiveRecord(client,organizationId,id,header.module);if(ok)await audit(client,{organizationId,userId,action:`${header.module}.deleted`,entityType:header.module,entityId:id});return ok})}
async function getHeaderInClient(client:PoolClient,organizationId:string,id:string){for(const moduleKey of Object.keys(moduleTables)){const rows=await selectRows(client,organizationId,moduleKey,id);if(rows[0])return {id,module:moduleKey,createdBy:text(rows[0].created_by_user_id)}}return null}
